import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class Solution {
    private Solution() {}

    public interface Freezable<T> {
        T freeze();
    }

    public static <T extends Freezable<T>> int pageCount(List<T> items, int pageSize) {
        validate(items, pageSize);
        return items.isEmpty() ? 0 : 1 + (items.size() - 1) / pageSize;
    }

    public static <T extends Freezable<T>> List<T> frozenPage(
            List<T> items, int pageSize, int pageIndex) {
        validate(items, pageSize);
        int pages = items.isEmpty() ? 0 : 1 + (items.size() - 1) / pageSize;
        if (pageIndex < 0 || pageIndex >= pages) {
            throw new IllegalArgumentException("page index out of range");
        }
        int from = pageIndex * pageSize;
        int to = Math.min(items.size(), from + pageSize);
        List<T> result = new ArrayList<T>(to - from);
        for (int i = from; i < to; i++) {
            T frozen = items.get(i).freeze();
            if (frozen == null) {
                throw new IllegalArgumentException("freeze returned null");
            }
            result.add(items.get(i));
        }
        return Collections.unmodifiableList(result);
    }

    private static <T> void validate(List<T> items, int pageSize) {
        if (items == null || pageSize <= 0) {
            throw new IllegalArgumentException("invalid list or page size");
        }
        for (T item : items) {
            if (item == null) {
                throw new IllegalArgumentException("null element");
            }
        }
    }
}

