import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SolutionTest {
    private static final class Box implements Solution.Freezable<Box> {
        final String value;
        int freezeCalls;

        Box(String value) {
            this.value = value;
        }

        public Box freeze() {
            freezeCalls++;
            return new Box(value + "!");
        }
    }

    private static final class NullFreezer implements Solution.Freezable<NullFreezer> {
        int calls;

        public NullFreezer freeze() {
            calls++;
            return null;
        }
    }

    public static void main(String[] args) {
        Box a = new Box("a");
        Box b = new Box("b");
        Box c = new Box("c");
        Box d = new Box("d");
        Box e = new Box("e");
        List<Box> input = new ArrayList<Box>(Arrays.asList(a, b, c, d, e));

        equal(3, Solution.pageCount(input, 2), "partial final page must count");
        equal(0, Solution.pageCount(Collections.<Box>emptyList(), 3), "empty page count");

        List<Box> page = Solution.frozenPage(input, 2, 1);
        equal(2, page.size(), "page size");
        equal("c!", page.get(0).value, "first frozen value");
        equal("d!", page.get(1).value, "second frozen value");
        equal(0, a.freezeCalls, "unselected element frozen");
        equal(0, b.freezeCalls, "unselected element frozen");
        equal(1, c.freezeCalls, "selected element freeze count");
        equal(1, d.freezeCalls, "selected element freeze count");
        equal(0, e.freezeCalls, "unselected element frozen");

        input.set(2, new Box("replacement"));
        equal("c!", page.get(0).value, "result is backed by input list");
        expectUOE(() -> page.add(new Box("x")));

        List<Box> last = Solution.frozenPage(input, 2, 2);
        equal(1, last.size(), "last partial page size");
        equal("e!", last.get(0).value, "last page value");

        expectIAE(() -> Solution.pageCount(null, 1));
        expectIAE(() -> Solution.pageCount(input, 0));
        expectIAE(() -> Solution.pageCount(input, -1));
        expectIAE(() -> Solution.frozenPage(input, 2, -1));
        expectIAE(() -> Solution.frozenPage(input, 2, 3));
        expectIAE(() -> Solution.frozenPage(Collections.<Box>emptyList(), 2, 0));

        List<Box> withNull = new ArrayList<Box>(Arrays.asList(new Box("ok"), null));
        expectIAE(() -> Solution.pageCount(withNull, 1));
        expectIAE(() -> Solution.frozenPage(withNull, 1, 0));

        NullFreezer nullFreezer = new NullFreezer();
        expectIAE(() -> Solution.frozenPage(Collections.singletonList(nullFreezer), 1, 0));
        equal(1, nullFreezer.calls, "freeze should be invoked once before null result rejection");
    }

    private static void expectIAE(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }

    private static void expectUOE(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
        }
    }

    private static void equal(int expected, int actual, String message) {
        if (expected != actual) throw new AssertionError(message + ": expected " + expected + ", got " + actual);
    }

    private static void equal(String expected, String actual, String message) {
        if (!expected.equals(actual)) throw new AssertionError(message + ": expected " + expected + ", got " + actual);
    }
}

